  (function () {   "use strict";    const API_BASE = "https://lypo-backend.onrender.com";          const $ = (id) => document.getElementById(id);   const textInput = $("textInput");   const voiceSelect = $("voiceSelect");   const exaggerationSlider = $("exaggerationSlider");   const exaggerationValue = $("exaggerationValue");   const temperatureSlider = $("temperatureSlider");   const temperatureValue = $("temperatureValue");   const pitchSlider = $("pitchSlider");   const pitchValue = $("pitchValue");   const charCount = $("charCount");   const creditCost = $("creditCost");   const generateBtn = $("generateBtn");   const generateBtnLabel = $("generateBtnLabel");   const statusPill = $("statusPill");   const progressText = $("progressText");   const outputSection = $("outputSection");   const audioPlayer = $("audioPlayer");   const downloadBtn = $("downloadBtn");   const newVoiceoverBtn = $("newVoiceoverBtn");   const creditsBalance = $("creditsBalance");    let userBalance = 0;   let isGenerating = false;   let referenceAudioUrl = null;        function removeAudio() {     console.log("Audio removal requested but not implemented");   }              async function init() {     console.log("🎙️ Initializing LYPO Voiceover Tool...");           setupEventListeners();           await checkAuth();           updateCharacterCount();      console.log("✅ Voiceover tool initialized");   }    function setupEventListeners() {          textInput.addEventListener("input", updateCharacterCount);     textInput.addEventListener("input", checkGenerateReady);           voiceSelect.addEventListener("change", checkGenerateReady);           exaggerationSlider.addEventListener("input", () => {       exaggerationValue.textContent = parseFloat(exaggerationSlider.value).toFixed(1);     });           temperatureSlider.addEventListener("input", () => {       temperatureValue.textContent = parseFloat(temperatureSlider.value).toFixed(1);     });           pitchSlider.addEventListener("input", () => {       const pitchLabels = ["X-Low", "Low", "Medium", "High", "X-High"];       pitchValue.textContent = pitchLabels[parseInt(pitchSlider.value)];     });                generateBtn.addEventListener("click", handleGenerate);           if (newVoiceoverBtn) {       newVoiceoverBtn.addEventListener("click", resetTool);     }   }              function updateCharacterCount() {     const text = textInput.value.trim();     const chars = text.length;           charCount.textContent = chars;           const cost = Math.ceil((chars / 1000) * 50);     creditCost.textContent = cost;           if (generateBtnLabel) {       generateBtnLabel.textContent = `Generate Voiceover (${cost} credits)`;     }      return cost;   }    function checkGenerateReady() {     const text = textInput.value.trim();     const cost = updateCharacterCount();                          const canGenerate = text.length > 0 &&       userBalance >= cost &&       !isGenerating;      generateBtn.disabled = !canGenerate;      if (text.length > 0 && userBalance < cost) {       setStatus("Insufficient credits", "error");     } else if (text.length > 0 && userBalance >= cost) {       if (referenceAudioUrl) {         setStatus("Ready to generate with voice cloning", "ready");       } else {         setStatus("Ready to generate (default voice)", "ready");       }     }   }              async function checkAuth() {     try {       const token = localStorage.getItem("lypo_token_v1");       if (!token) {         console.log("⚠️ No token found");         if (creditsBalance) {           creditsBalance.textContent = "Login to see balance";           creditsBalance.style.cursor = "pointer";           creditsBalance.onclick = () => window.location.href = "auth.html";         }         generateBtn.disabled = true;         setStatus("Please login to generate voiceovers", "error");         return;       }        console.log("🔐 Checking authentication...");       const res = await fetch(`${API_BASE}/api/auth/me`, {         headers: { Authorization: `Bearer ${token}` },       });        if (!res.ok) {         throw new Error("Auth failed");       }        const data = await res.json();       console.log("✅ Auth successful:", data);        if (data.user) {                  const balance = data.user.balance ?? data.user.credits ?? 0;         console.log("💰 Balance value:", balance);          userBalance = balance;          if (creditsBalance) {           creditsBalance.textContent = `${balance} Credits`;           creditsBalance.style.cursor = "pointer";           creditsBalance.onclick = () => {             window.location.href = "index.html#buycredits";           };         }          checkGenerateReady();       }     } catch (err) {       console.error("❌ Auth check failed:", err);       if (creditsBalance) {         creditsBalance.textContent = "Login required";         creditsBalance.style.cursor = "pointer";         creditsBalance.onclick = () => window.location.href = "auth.html";       }       generateBtn.disabled = true;       setStatus("Please login to continue", "error");     }   }              async function handleGenerate() {     if (isGenerating) return;      const text = textInput.value.trim();     const voice = voiceSelect.value;     const exaggeration = parseFloat(exaggerationSlider.value);      const temperature = parseFloat(temperatureSlider.value);      const pitchOptions = ["x-low", "low", "medium", "high", "x-high"];     const pitch = pitchOptions[parseInt(pitchSlider.value)];      const cost = updateCharacterCount();      if (!text) {       setStatus("Please enter text to convert", "error");       return;     }      if (userBalance < cost) {       setStatus("Insufficient credits", "error");       return;     }      try {       isGenerating = true;       generateBtn.disabled = true;       generateBtn.classList.add("generating");               if (window.GeneratingModal) {         window.GeneratingModal.show(           "Generating Voiceover...",           "AI is creating your professional voiceover.<br>This may take 30-60 seconds."         );       }        outputSection.style.display = "none";        setStatus("Starting Chatterbox Pro generation...", "loading");        const token = localStorage.getItem("lypo_token_v1");       if (!token) {         throw new Error("Please login to continue");       }               console.log("🎙️ Submitting Chatterbox Pro voiceover request...");       console.log(`   Text length: ${text.length} chars`);       console.log(`   Voice: ${voice}`);       console.log(`   Exaggeration: ${exaggeration}`);       console.log(`   Temperature (cfg): ${temperature}`);       console.log(`   Pitch: ${pitch}`);        const response = await fetch(`${API_BASE}/api/voiceover/generate`, {         method: "POST",         headers: {           "Content-Type": "application/json",           Authorization: `Bearer ${token}`,         },         body: JSON.stringify({           text: text,           voice: voice,           exaggeration: exaggeration,           temperature: temperature,           pitch: pitch,         }),       });        if (!response.ok) {         const errorData = await response.json();         throw new Error(errorData.error || "Generation failed");       }        const data = await response.json();       console.log("✅ Voiceover request submitted:", data);        if (!data.jobId) {         throw new Error("No job ID received");       }               await pollVoiceoverStatus(data.jobId);      } catch (error) {       console.error("❌ Generation error:", error);       setStatus(error.message || "Generation failed", "error");       isGenerating = false;       generateBtn.disabled = false;       generateBtn.classList.remove("generating");               if (window.GeneratingModal) {         window.GeneratingModal.hide(false);       }     }   }    async function pollVoiceoverStatus(jobId) {     console.log("⏳ Polling voiceover status for job:", jobId);      const token = localStorage.getItem("lypo_token_v1");     const maxAttempts = 60;      let attempts = 0;      const poll = async () => {       try {         attempts++;          if (attempts > maxAttempts) {           throw new Error("Generation timeout. Please try again.");         }          const response = await fetch(`${API_BASE}/api/voiceover/status/${jobId}`, {           headers: { Authorization: `Bearer ${token}` },         });          if (!response.ok) {           throw new Error("Failed to check status");         }          const data = await response.json();         console.log(`📊 Status check ${attempts}:`, data.status);          if (data.status === "completed" && data.audioUrl) {                      console.log("✅ Voiceover generated successfully!");           setStatus("Voiceover complete!", "success");                       if (data.remainingCredits !== undefined) {             userBalance = data.remainingCredits;             if (creditsBalance) {               creditsBalance.textContent = `${userBalance} Credits`;             }           }                       displayAudio(data.audioUrl);            isGenerating = false;           generateBtn.disabled = false;           generateBtn.classList.remove("generating");                       if (window.GeneratingModal) {             window.GeneratingModal.hide(true);           }          } else if (data.status === "failed") {           throw new Error(data.error || "Generation failed");          } else {                      let statusMsg;           const elapsed = attempts * 5;            if (data.status === "starting") {             if (elapsed < 15) {               statusMsg = `⏳ Starting Chatterbox Pro... (${elapsed}s)`;             } else if (elapsed < 30) {               statusMsg = `⏳ Initializing AI model... (${elapsed}s)`;             } else if (elapsed < 60) {               statusMsg = `⏳ Loading model - Almost ready... (${elapsed}s)`;             } else {               statusMsg = `⏳ Preparing (${elapsed}s) - First generation takes longer`;             }           } else if (data.status === "processing") {             statusMsg = `⚡ Generating voiceover with Chatterbox Pro... (${elapsed}s)`;           } else {             statusMsg = `Status: ${data.status} (${elapsed}s)`;           }            setStatus(statusMsg, "loading");                       setTimeout(poll, 5000);         }        } catch (error) {         console.error("❌ Polling error:", error);         setStatus(error.message || "Failed to generate voiceover", "error");         isGenerating = false;         generateBtn.disabled = false;         generateBtn.classList.remove("generating");                   if (window.GeneratingModal) {           window.GeneratingModal.hide(false);         }       }     };           setTimeout(poll, 2000);    }    function displayAudio(audioUrl) {     console.log("🎵 Displaying audio:", audioUrl);           audioPlayer.src = audioUrl;     audioPlayer.load();           downloadBtn.onclick = async (e) => {       e.preventDefault();       try {         console.log("📥 Downloading audio...");         const response = await fetch(audioUrl);         const blob = await response.blob();         const url = window.URL.createObjectURL(blob);         const a = document.createElement('a');         a.href = url;         a.download = `lypo-voiceover-${Date.now()}.mp3`;         document.body.appendChild(a);         a.click();         document.body.removeChild(a);         window.URL.revokeObjectURL(url);         console.log("✅ Download started!");       } catch (error) {         console.error("❌ Download failed:", error);                  window.open(audioUrl, '_blank');       }     };           outputSection.style.display = "block";           setTimeout(() => {       outputSection.scrollIntoView({ behavior: "smooth", block: "center" });     }, 300);   }    function resetTool() {     console.log("🔄 Resetting tool...");           textInput.value = "";     voiceSelect.selectedIndex = 0;     exaggerationSlider.value = 0.5;     exaggerationValue.textContent = "0.5";     temperatureSlider.value = 0.5;     temperatureValue.textContent = "0.5";     pitchSlider.value = 2;     pitchValue.textContent = "Medium";           removeAudio();           outputSection.style.display = "none";     audioPlayer.src = "";     isGenerating = false;     generateBtn.disabled = false;     generateBtn.classList.remove("generating");           updateCharacterCount();     checkGenerateReady();      setStatus("Ready", "ready");           window.scrollTo({ top: 0, behavior: "smooth" });   }              function setStatus(message, type = "info") {     if (!progressText || !statusPill) return;      progressText.textContent = message;           statusPill.classList.remove("active", "error", "success");      if (type === "loading") {       statusPill.classList.add("active");       statusPill.querySelector(".loader").style.opacity = "1";       statusPill.querySelector(".ping").style.opacity = "0";     } else if (type === "error") {       statusPill.classList.add("error");       statusPill.querySelector(".loader").style.opacity = "0";       statusPill.querySelector(".ping").style.opacity = "0";     } else if (type === "success") {       statusPill.classList.add("success");       statusPill.querySelector(".loader").style.opacity = "0";       statusPill.querySelector(".ping").style.opacity = "1";     } else {              statusPill.querySelector(".loader").style.opacity = "0";       statusPill.querySelector(".ping").style.opacity = "0.6";     }      console.log(`📊 Status: ${message} (${type})`);   }                 if (document.readyState === "loading") {     document.addEventListener("DOMContentLoaded", init);   } else {     init();   } })(); 